elsif PSTATE.EL == EL2 then
    if HaveEL(EL3) && IsFeatureImplemented(FEAT_AA64EL3) && !ELUsingAArch32(EL3) && CPTR_EL3().TAM == '1' then
        if EL3SDDUndef() then
            Undefined();
        else
            AArch64_AArch32SystemAccessTrap(EL3, 0x04);
        end;
    elsif !IsHighestEL(PSTATE.EL) && IsFeatureImplemented(FEAT_AA64) && AMCR_EL0().CG1RZ == '1' then
        R(t, t2) = Zeros{64};
    elsif !IsHighestEL(PSTATE.EL) && !IsFeatureImplemented(FEAT_AA64) && AMCR().CG1RZ == '1' then
        R(t, t2) = Zeros{64};
    else
        R(t, t2) = AMEVCNTR1(m);
    end;
elsif PSTATE.EL == EL3 then
    R(t, t2) = AMEVCNTR1(m);
end;

let m:integer = UInt(CRm[0] :: opc1[2:0]);

if !(IsFeatureImplemented(FEAT_AMUv1) && IsFeatureImplemented(FEAT_AA32)) then
    Undefined();
elsif m >= NUM_AMU_CG1_MONITORS then
    Undefined();
elsif !IsG1ActivityMonitorImplemented(m) then
    Undefined();
elsif PSTATE.EL == EL1 && EL2Enabled() && IsFeatureImplemented(FEAT_AA64EL2) && !ELUsingAArch32(EL2) && m >= 8 && HSTR_EL2().T5 == '1' then
    AArch64_AArch32SystemAccessTrap(EL2, 0x04);
elsif PSTATE.EL == EL1 && EL2Enabled() && IsFeatureImplemented(FEAT_AA32EL2) && ELUsingAArch32(EL2) && m >= 8 && HSTR().T5 == '1' then
    AArch32_TakeHypTrapException(0x04);
elsif IsHighestEL(PSTATE.EL) then
    AMEVCNTR1(m) = R(t2) :: R(t);
else
    Undefined();
end;
